\section{Algorithm}
\begin{algorithm}[htbp]
\caption{Score computation}
\label{alg:score}
\begin{algorithmic}[1]
\Require A graph $G=(V,E)$ with $n$ nodes and $m$ edges
\Ensure The score $score[v]$ of each node $v \in V$
\For{each node $v \in V$}
    \State update $score[v]$
\EndFor
\State \textbf{return} $scores$
\end{algorithmic}
\end{algorithm}
